import manifest from "@/data/image-manifest.json";

export type ImageMeta = { src: string; width: number; height: number; blur: string };

const data = manifest as unknown as Record<string, ImageMeta | ImageMeta[]>;

/** Generated by `npm run assets`. Undefined when the source file was missing. */
export function getPortrait(): ImageMeta | undefined {
  const p = data.portrait;
  return p && !Array.isArray(p) ? p : undefined;
}

export function getProjectImages(slug: string): ImageMeta[] {
  const p = data[slug];
  return Array.isArray(p) ? p : [];
}
